From 1006b8972b67e868c857999cb7d9aea2606c43cf Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:37:25 +0100
Subject: [PATCH] applets/notifications: Don't dodge a dialog if that pushes
 popups off screen

On short screens, the popup moved past an obstructing dialog, like the
panel configuration, even when it then ended up partially off screen.
Only dodge the dialog if the popup still fits, otherwise overlap it.

BUG: 488538
---
 applets/notifications/global/Globals.qml | 10 ++++++++--
 1 file changed, 8 insertions(+), 2 deletions(-)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..22f5be1757 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -394,7 +394,10 @@ QtObject {
                 // positioning it again, hence the temporary Qt.rect with explicit "y" and not just the popup as a whole
                 if (obstructingDialog && obstructingDialog.visible
                         && rectIntersect(obstructingDialog, Qt.rect(popup.x, y, popup.width, popup.height))) {
-                    y = obstructingDialog.y + obstructingDialog.height + popupEdgeDistance;
+                    const dodgedY = obstructingDialog.y + obstructingDialog.height + popupEdgeDistance;
+                    if (dodgedY + popup.height <= screenRect.y + screenRect.height - popupEdgeDistance) {
+                        y = dodgedY;
+                    }
                 }
                 popup.y = y;
                 // If the popup isn't ready yet, ignore its occupied space for now.
@@ -404,7 +407,10 @@ QtObject {
                 y -= popup.height;
                 if (obstructingDialog && obstructingDialog.visible
                         && rectIntersect(obstructingDialog, Qt.rect(popup.x, y, popup.width, popup.height))) {
-                    y = obstructingDialog.y - popup.height - popupEdgeDistance;
+                    const dodgedY = obstructingDialog.y - popup.height - popupEdgeDistance;
+                    if (dodgedY >= screenRect.y + popupEdgeDistance) {
+                        y = dodgedY;
+                    }
                 }
                 popup.y = y;
                 if (popup.height > 0) {
-- 
